"""The ``record_*_metric`` functions the turn lifecycle calls.

Measurements are fire-and-forget and carry no per-operation state. Every
function is a safe no-op until instruments are registered, so call sites
never need to check configuration. Functions construct metric attributes
internally — IDs, content, and exception messages are never metric
attributes.
"""

from __future__ import annotations

from opentelemetry.metrics import Histogram

from rasa.tracing.shared.instrument_registry import get_registered_instrument
from rasa.tracing.turn import semconv
from rasa.tracing.turn.attribute_values import (
    TurnOutcome,
    TurnOutputModality,
    TurnTriggerType,
)


def record_turn_duration_metric(
    seconds: float,
    *,
    input_type: TurnTriggerType,
    outcome: TurnOutcome,
) -> None:
    """Record the duration of one engine turn.

    Args:
        seconds: Time from processing start to the terminal state, in seconds.
            Negative values are skipped.
        input_type: Input or timeout that triggered the turn.
        outcome: Terminal state of the turn.
    """
    instrument = get_registered_instrument(semconv.METRIC_TURN_DURATION)
    if not isinstance(instrument, Histogram) or seconds < 0:
        return
    instrument.record(
        seconds,
        {
            semconv.METRIC_ATTR_TURN_INPUT_TYPE: input_type.value,
            semconv.METRIC_ATTR_TURN_OUTCOME: outcome.value,
        },
    )


def record_turn_time_to_first_output_metric(
    seconds: float,
    *,
    input_type: TurnTriggerType,
    output_type: TurnOutputModality,
) -> None:
    """Record latency from the turn trigger to its first output.

    Args:
        seconds: Time from the input trigger to the first output in the
            expected modality, in seconds. Negative values are skipped.
        input_type: Input or timeout that triggered the turn.
        output_type: Modality of the first output.
    """
    instrument = get_registered_instrument(semconv.METRIC_TURN_TIME_TO_FIRST_OUTPUT)
    if not isinstance(instrument, Histogram) or seconds < 0:
        return
    instrument.record(
        seconds,
        {
            semconv.METRIC_ATTR_TURN_INPUT_TYPE: input_type.value,
            semconv.METRIC_ATTR_TURN_OUTPUT_TYPE: output_type.value,
        },
    )
